from functools import reduce
from math import gcd


def _progression(indices, maxdim):
    best = (0, None, [])
    for step in range(2, min(12, maxdim) + 1):
        for residue in range(step):
            seq = [i for i in indices if i % step == residue]
            if len(seq) > best[0]:
                best = (len(seq), step, seq)
    return best


def _period(indices):
    return reduce(gcd, (b - a for a, b in zip(indices, indices[1:])))


def transform(grid):
    height, width = len(grid), len(grid[0])
    choices = []
    for color in {value for row in grid for value in row}:
        row_candidates = [r for r, row in enumerate(grid)
                          if sum(value == color for value in row) >= 0.7 * width]
        col_candidates = [c for c in range(width)
                          if sum(grid[r][c] == color for r in range(height)) >= 0.7 * height]
        row_prog = _progression(row_candidates, height)
        col_prog = _progression(col_candidates, width)
        row_rate = row_prog[0] / len(row_candidates) if row_candidates else 0
        col_rate = col_prog[0] / len(col_candidates) if col_candidates else 0
        if row_prog[0] >= 2 and col_prog[0] >= 2 and row_rate >= 0.8 and col_rate >= 0.8:
            rows_in_prog = row_prog[2]
            cols_in_prog = col_prog[2]
            choices.append((min(row_rate, col_rate), row_prog[0] + col_prog[0], color,
                            rows_in_prog, cols_in_prog))

    _, _, line_color, detected_rows, detected_cols = max(choices)
    row_step = _period(detected_rows)
    col_step = _period(detected_cols)
    rows = list(range(detected_rows[0], detected_rows[-1] + 1, row_step))
    cols = list(range(detected_cols[0], detected_cols[-1] + 1, col_step))
    fill_color = Counter(value for row in grid for value in row if value != line_color).most_common(1)[0][0]

    output = []
    for r1, r2 in zip(rows, rows[1:]):
        result_row = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            if len(set(corners)) == 1 and corners[0] != line_color:
                result_row.append(corners[0])
            else:
                result_row.append(fill_color)
        output.append(result_row)

    while output and all(value == fill_color for value in output[0]):
        output.pop(0)
    while output and all(value == fill_color for value in output[-1]):
        output.pop()
    while output and output[0] and all(row[0] == fill_color for row in output):
        for row in output:
            row.pop(0)
    while output and output[0] and all(row[-1] == fill_color for row in output):
        for row in output:
            row.pop()
    return output or [[fill_color]]
